import{_ as n,C as i,o as l,c as h,ag as o,E as s,j as t,a as r}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"Magic AI for Sellers","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/magic-ai.md","filePath":"catalog/magic-ai.md","lastUpdated":1787568847000}'),g={name:"catalog/magic-ai.md"};function d(c,e,p,u,m,f){const a=i("ImagePopup");return l(),h("div",null,[e[0]||(e[0]=o('<h1 id="magic-ai-for-sellers" tabindex="-1">Magic AI for Sellers <a class="header-anchor" href="#magic-ai-for-sellers" aria-label="Permalink to &quot;Magic AI for Sellers&quot;">​</a></h1><p><strong>Magic AI</strong> lets a seller describe a product in a sentence or two and have the marketplace write the listing for them — descriptions, attribute values and suggested categories — instead of filling every field by hand. The admin decides whether it is available at all, which model writes the content, how much each seller may generate, and how far the AI is allowed to reach into a listing.</p><p>This page covers the whole feature: what a new marketplace starts with, then every setting in the admin panel in the order the panel presents it, how those settings depend on one another, and what a seller actually sees.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>The settings a freshly installed marketplace starts with</li><li>Every Magic AI setting in the admin panel, explained one by one</li><li>How the settings depend on each other</li><li>What a seller experiences, and what stops them</li></ul></div><h2 id="what-magic-ai-does" tabindex="-1">What Magic AI does <a class="header-anchor" href="#what-magic-ai-does" aria-label="Permalink to &quot;What Magic AI does&quot;">​</a></h2><p>When Magic AI is available, a <strong>Generate content</strong> button appears in the header of the seller&#39;s product edit form. The seller writes a short description of the product, optionally attaches reference photos, and the AI proposes values for the listing&#39;s fields — plus a set of categories. The seller reviews every proposal and chooses what to apply.</p><p>Two things are worth understanding before any of the settings make sense:</p><ul><li><strong>Magic AI writes text, it does not create images.</strong> Photos a seller attaches are only <em>read</em> by the AI to inform what it writes.</li><li><strong>Applying a result only fills the form.</strong> Nothing reaches the catalog until the seller saves the product, and the listing still goes through the normal <a href="/catalog/product-management#drafts-submission-and-approval">approval flow</a>.</li></ul><h2 id="default-settings" tabindex="-1">Default settings <a class="header-anchor" href="#default-settings" aria-label="Permalink to &quot;Default settings&quot;">​</a></h2><p>A newly installed marketplace ships Magic AI <strong>switched off</strong>, with sensible-but-cautious values behind the switch. Nothing generates until you deliberately turn it on and connect an AI provider.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default on a new marketplace</th><th>Meaning of that default</th></tr></thead><tbody><tr><td><strong>Enabled</strong> (Magic AI, application-wide)</td><td>Off</td><td>Magic AI is inert everywhere</td></tr><tr><td><strong>Provider API keys</strong></td><td>Empty</td><td>No AI provider is connected</td></tr><tr><td><strong>Enable</strong> (Product Content Generation)</td><td>Off</td><td>Sellers cannot generate, even if the above is on</td></tr><tr><td><strong>Model</strong></td><td>Not set</td><td>Falls back to the default text model</td></tr><tr><td><strong>Allow Reference Images</strong></td><td>On</td><td>Sellers may attach photos — once generation itself is enabled</td></tr><tr><td><strong>Vision Model</strong></td><td>Not set</td><td>Falls back to <strong>Model</strong></td></tr><tr><td><strong>Maximum Reference Images</strong></td><td>3</td><td>At most three photos per generation</td></tr><tr><td><strong>Let Sellers Choose Fields</strong></td><td>Off</td><td>Every eligible field is generated; the seller cannot narrow it</td></tr><tr><td><strong>Overwrite Filled Attributes</strong></td><td>Off</td><td>Only empty fields are proposed</td></tr><tr><td><strong>Per Seller Limit</strong></td><td>Blank</td><td>Unlimited generations</td></tr><tr><td><strong>Limit Period</strong></td><td>Monthly</td><td>Usage is counted per calendar month</td></tr><tr><td><strong>Select Attributes</strong></td><td>Off</td><td>Every attribute the seller can edit is eligible</td></tr><tr><td><strong>Suggest Categories</strong></td><td>On</td><td>The AI proposes categories</td></tr><tr><td><strong>Magic AI Enabled</strong> (per seller)</td><td>On</td><td>Every seller inherits access</td></tr><tr><td><strong>Magic AI Generation Limit</strong> (per seller)</td><td>Blank</td><td>The seller follows the marketplace-wide limit</td></tr></tbody></table><h3 id="why-the-defaults-are-shaped-this-way" tabindex="-1">Why the defaults are shaped this way <a class="header-anchor" href="#why-the-defaults-are-shaped-this-way" aria-label="Permalink to &quot;Why the defaults are shaped this way&quot;">​</a></h3><p><strong>Off by default, everywhere.</strong> Generation costs money at the AI provider and puts words on your storefront. Two separate switches must be turned on before any seller can spend a single generation, so the feature can never start running because somebody enabled something adjacent.</p><p><strong>Cautious about overwriting.</strong> <strong>Overwrite Filled Attributes</strong> starts <em>off</em>, so a seller who has already written a careful description will not have it replaced by a machine. The AI fills the gaps and leaves the rest alone. A seller who runs a generation on an already-complete listing is told <strong>Nothing left to fill</strong> rather than having their work quietly rewritten.</p><p><strong>Generous about reach.</strong> <strong>Select Attributes</strong> starts <em>off</em> and <strong>Suggest Categories</strong> starts <em>on</em>, so the first generation a seller runs is as useful as possible. You can narrow the reach later once you have seen what the AI proposes on your catalog.</p><p><strong>Unlimited but measured.</strong> There is no generation cap out of the box, but the counting window is already set to <strong>Monthly</strong>, so the moment you type a number into <strong>Per Seller Limit</strong> it behaves sensibly without any further setup.</p><h2 id="magic-ai-→-general" tabindex="-1">Magic AI → General <a class="header-anchor" href="#magic-ai-→-general" aria-label="Permalink to &quot;Magic AI → General&quot;">​</a></h2><p>Go to <strong>Configure → Magic AI → General</strong>. This screen holds a single switch, and it is the one every other Magic AI setting hangs from.</p><p>Nothing here is marketplace-specific — it governs Magic AI everywhere in Bagisto, including the admin&#39;s own AI tools and the storefront features. Turning it on does not hand anything to sellers by itself; it only makes the rest of the chain possible.</p>',19)),s(a,{src:"/images/magic-ai/magic-ai-general.png",alt:"Magic AI General settings with the application-wide Enabled toggle"}),e[1]||(e[1]=o('<h3 id="enabled" tabindex="-1">Enabled <a class="header-anchor" href="#enabled" aria-label="Permalink to &quot;Enabled&quot;">​</a></h3><p>The application-wide switch for Magic AI — every Magic AI feature in Bagisto, not just the marketplace ones.</p><ul><li><strong>When off</strong> — nothing generates anywhere. Sellers do not see a <strong>Generate content</strong> button; if one is somehow reached, the marketplace answers <em>Content generation is currently turned off for this store.</em></li><li><strong>When on</strong> — Magic AI becomes <em>available</em> to be configured. It does <strong>not</strong> by itself give sellers anything; the marketplace switch in Part 2.3 is still required.</li></ul><p><strong>Affects:</strong> admin, sellers, and storefront AI features alike. This is the top of the chain.</p><h2 id="magic-ai-→-providers" tabindex="-1">Magic AI → Providers <a class="header-anchor" href="#magic-ai-→-providers" aria-label="Permalink to &quot;Magic AI → Providers&quot;">​</a></h2><p>Go to <strong>Configure → Magic AI → Providers</strong>. This is where the marketplace is given an AI account to work with.</p><p>Bagisto does not ship its own AI. Every generation is a call to an outside provider using credentials you supply, and that provider bills you for it — so until this screen is filled in, nothing can generate.</p>',7)),s(a,{src:"/images/magic-ai/magic-ai-providers.png",alt:"Magic AI provider list with an API Key field for each provider"}),e[2]||(e[2]=o('<p>Each supported provider — <strong>OpenAI</strong>, <strong>Anthropic</strong>, <strong>Gemini</strong>, <strong>Groq</strong>, <strong>xAI</strong>, <strong>DeepSeek</strong>, <strong>Mistral</strong> and <strong>Ollama</strong> — has its own <strong>API Key</strong> field. <strong>Ollama</strong> additionally has a <strong>URL</strong>, because it runs on a server you host yourself rather than a vendor&#39;s; it is pre-filled with the address Ollama uses on the machine it is installed on.</p><p>You do not have to fill in all of them; you need credentials for whichever provider owns the model you intend to use.</p><p><strong>Why it exists:</strong> the marketplace does not have its own AI. It calls out to a provider using your account, and the provider bills you. Because the key is held centrally, <strong>sellers never see or supply credentials</strong> — they simply get a working button.</p><p><strong>When it is empty:</strong> the <strong>Generate content</strong> button may still appear, but a generation cannot complete. The seller sees <em>Couldn&#39;t generate content just now</em> and — importantly — <strong>is not charged a generation</strong> for the failure.</p><div class="warning custom-block"><p class="custom-block-title">A key is a prerequisite, not a setting you can skip</p><p>Turning on every switch below without connecting a provider produces a button that always fails. Configure the provider first, then enable the feature.</p></div><h2 id="magic-ai-→-marketplace-features" tabindex="-1">Magic AI → Marketplace Features <a class="header-anchor" href="#magic-ai-→-marketplace-features" aria-label="Permalink to &quot;Magic AI → Marketplace Features&quot;">​</a></h2><p>Go to <strong>Configure → Magic AI → Marketplace Features</strong>. This tile is the marketplace&#39;s own, and it holds three sections: <strong>Product Content Generation</strong>, <strong>Limits</strong> and <strong>Scope</strong>.</p><h3 id="product-content-generation" tabindex="-1">Product Content Generation <a class="header-anchor" href="#product-content-generation" aria-label="Permalink to &quot;Product Content Generation&quot;">​</a></h3><p>This is the section that decides whether your sellers get the feature at all, which model writes for them, and how much freedom they have over the result.</p><p>Its seven settings fall into three groups: the switch itself, the two model choices and the image rules that go with them, and two settings that shape how much of a listing the AI is allowed to touch.</p>',10)),s(a,{src:"/images/magic-ai/product-content-generation.png",alt:"Product Content Generation settings — Enable, Model, Allow Reference Images, Vision Model, Maximum Reference Images, Let Sellers Choose Fields and Overwrite Filled Attributes"}),e[3]||(e[3]=o('<h4 id="enable" tabindex="-1">Enable <a class="header-anchor" href="#enable" aria-label="Permalink to &quot;Enable&quot;">​</a></h4><p>The marketplace&#39;s own master switch for seller content generation.</p><ul><li><strong>When off</strong> — no seller can generate product content, <strong>regardless of their individual setting</strong>. A seller whose own Magic AI is switched on is still blocked.</li><li><strong>When on</strong> — combined with the application-wide <strong>Enabled</strong> above, sellers become eligible.</li></ul><p><strong>Affects:</strong> sellers only. Nothing on the storefront changes directly, though the listings sellers publish are of course what shoppers eventually read.</p><h5 id="what-switching-it-on-actually-changes" tabindex="-1">What switching it on actually changes <a class="header-anchor" href="#what-switching-it-on-actually-changes" aria-label="Permalink to &quot;What switching it on actually changes&quot;">​</a></h5><p>The admin screen itself barely changes — the toggle moves and the other settings stay visible either way. The difference shows up on the seller&#39;s product form.</p><p><strong>Before.</strong> With generation off, the product edit header carries only <strong>Back</strong> and <strong>Save Product</strong>. There is no route into the feature at all; a seller has no way of knowing it exists.</p>',7)),s(a,{src:"/images/magic-ai/seller-form-without-magic-ai.png",alt:"Seller product form header with only Back and Save Product, before Magic AI is enabled"}),e[4]||(e[4]=t("p",null,[t("strong",null,"After."),r(" With both master switches on, a "),t("strong",null,"Generate content"),r(" button appears in the same header, between "),t("strong",null,"Back"),r(" and "),t("strong",null,"Save Product"),r(".")],-1)),s(a,{src:"/images/magic-ai/seller-form-with-magic-ai.png",alt:"Seller product form header showing the Generate content button after Magic AI is enabled"}),e[5]||(e[5]=o('<p>The button appearing is not the same as generation working — it appears on the strength of the switches and the seller&#39;s own permission, while a missing provider key only reveals itself when the seller presses it.</p><h4 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;Model&quot;">​</a></h4><p>The model used for <strong>text-only</strong> generation — that is, when the seller attaches no reference photos.</p><p>The dropdown lists every text model the platform knows about, each labelled with its provider, for example <strong>OpenAI: GPT-5.2</strong> or <strong>Anthropic: Claude Sonnet 4.6</strong>. Pick one whose provider you entered a key for.</p><p><strong>If you leave it blank</strong>, generation falls back to the platform&#39;s default text model. That is a working fallback, not a recommendation — set this deliberately so you know which model your marketplace is paying for.</p><p><strong>Practical example:</strong> a marketplace selling technical parts may prefer a larger, more accurate model here; a marketplace with thousands of simple fashion listings may prefer a smaller, cheaper one, since the descriptions are short and formulaic.</p><h4 id="allow-reference-images" tabindex="-1">Allow Reference Images <a class="header-anchor" href="#allow-reference-images" aria-label="Permalink to &quot;Allow Reference Images&quot;">​</a></h4><p>Whether sellers may attach product photos for the AI to read.</p><ul><li><strong>When on</strong> — the seller&#39;s dialog offers <strong>Add images</strong>, and the AI sees the photos alongside the written description. This produces markedly better colour, material and style values, because the AI is describing something it can see rather than guessing from a sentence.</li><li><strong>When off</strong> — the image area disappears from the seller&#39;s dialog entirely, and the seller may attach nothing.</li></ul><p><strong>Requires a vision-capable model.</strong> A model that cannot read images will not become able to just because this is switched on.</p><h4 id="vision-model" tabindex="-1">Vision Model <a class="header-anchor" href="#vision-model" aria-label="Permalink to &quot;Vision Model&quot;">​</a></h4><p>The model used <strong>when a seller attaches reference images</strong>. It may be the same as <strong>Model</strong>.</p><p>This setting only appears while <strong>Allow Reference Images</strong> is on. <strong>If you leave it blank, it falls back to Model</strong> — so a marketplace that has chosen one model capable of both text and vision can simply set <strong>Model</strong> and ignore this field.</p><p><strong>Why it is separate:</strong> vision-capable models are often more expensive. Splitting the two lets you run cheap text generations by default and only pay the higher rate when a seller actually attaches photos.</p><h4 id="maximum-reference-images" tabindex="-1">Maximum Reference Images <a class="header-anchor" href="#maximum-reference-images" aria-label="Permalink to &quot;Maximum Reference Images&quot;">​</a></h4><p>How many photos a seller may attach to a single generation. <strong>Defaults to 3.</strong> Only appears while <strong>Allow Reference Images</strong> is on.</p><p>The number is enforced when the seller submits, and the seller&#39;s dialog shows their progress against it — <em>2 of 3 added · JPG, PNG or WebP up to 2 MB</em>. Each individual file must be a <strong>JPG, PNG or WebP of no more than 2 MB</strong>; a larger file is skipped with <em>That file was skipped — images must be under 2 MB.</em></p><p><strong>Setting it to 0</strong> allows no images at all, which is the same practical outcome as switching <strong>Allow Reference Images</strong> off.</p><p><strong>Why it exists:</strong> every attached image increases what the provider charges for the call. Three is a balance between giving the AI enough to look at and keeping a single generation cheap.</p><h4 id="let-sellers-choose-fields" tabindex="-1">Let Sellers Choose Fields <a class="header-anchor" href="#let-sellers-choose-fields" aria-label="Permalink to &quot;Let Sellers Choose Fields&quot;">​</a></h4><p>Whether a seller may narrow a generation to a subset of fields.</p><ul><li><strong>When on</strong> — the seller&#39;s dialog shows a <strong>Fields to fill</strong> list with <strong>Select all</strong> and <strong>Clear all</strong>, and the seller ticks exactly which fields the AI should propose.</li><li><strong>When off</strong> — every eligible field is generated and the seller cannot narrow the set.</li></ul><p><strong>Practical example:</strong> a seller who is happy with their description but wants the AI to fill in material, colour and care instructions can, with this on, ask for only those three — a faster, cheaper, more predictable result. With it off, they must accept a proposal for everything and simply decline what they do not want.</p><h4 id="overwrite-filled-attributes" tabindex="-1">Overwrite Filled Attributes <a class="header-anchor" href="#overwrite-filled-attributes" aria-label="Permalink to &quot;Overwrite Filled Attributes&quot;">​</a></h4><p>Whether fields that already have a value are eligible for generation.</p><ul><li><strong>When on</strong> — the AI proposes values for <strong>every</strong> eligible field, filled or not. In the review step, a proposal that replaces something is marked <strong>replaces</strong>, with the previous value struck through, so nothing is lost silently.</li><li><strong>When off</strong> — <strong>only attributes that are still empty are proposed.</strong> Fields a seller has already written are never touched.</li></ul><p><strong>How this feels to a seller:</strong> with it off, a seller who runs a generation on a complete listing is told <strong>Nothing left to fill</strong> — <em>Every eligible field already has a value. Clear a field first, or ask the store admin to allow overwriting.</em> That message is the direct consequence of this setting, and it is the most common Magic AI support question on a marketplace that leaves it off.</p><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><p>Every generation costs you money at the provider, so this section caps how freely sellers can spend it.</p><p>The two settings only mean anything together: one is the number of generations, the other is the window that number is counted in. Leave the number blank and the window becomes irrelevant, because there is nothing to count against.</p>',30)),s(a,{src:"/images/magic-ai/marketplace-features-limits.png",alt:"Limits section with Per Seller Limit and Limit Period"}),e[6]||(e[6]=o('<h4 id="per-seller-limit" tabindex="-1">Per Seller Limit <a class="header-anchor" href="#per-seller-limit" aria-label="Permalink to &quot;Per Seller Limit&quot;">​</a></h4><p>The maximum number of generations <strong>each</strong> seller may run within the period below. It is a per-seller allowance, not a shared marketplace pool — a limit of 50 across 20 sellers means each of them gets 50.</p><ul><li><strong>Leave it blank for unlimited.</strong></li><li><strong>Set it to 0</strong> to allow no generations at all — the feature stays visible but every attempt is refused.</li><li><strong>Individual sellers can override it</strong> — see <a href="#per-seller-controls">Per-seller controls</a> below.</li></ul><h4 id="limit-period" tabindex="-1">Limit Period <a class="header-anchor" href="#limit-period" aria-label="Permalink to &quot;Limit Period&quot;">​</a></h4><p>The window the per-seller limit is counted over: <strong>Daily</strong> or <strong>Monthly</strong>.</p><ul><li><strong>Daily</strong> — the count resets at the start of each day, so a limit of 5 means five generations every day.</li><li><strong>Monthly</strong> — the count resets at the start of each calendar month.</li></ul><p>The two settings are only meaningful together: <strong>Per Seller Limit</strong> is the number, <strong>Limit Period</strong> is the window it is counted in. Changing the period does not erase past usage; it changes which past generations still count towards the current window.</p><p><strong>Only successful generations count.</strong> If the AI provider fails to respond, the seller is told <em>this didn&#39;t use up one of your generations</em>, and it does not. Regenerating a single field in the review step, however, <strong>does</strong> use one generation — the seller&#39;s dialog says so.</p><h3 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><p>Scope answers a different question from the settings above: not <em>whether</em> the AI may write, but <em>how far into a listing it may reach</em>.</p><p>By default it reaches everywhere the seller can edit. These three settings let you pull it back to a named set of attributes, and decide whether it is trusted to place products into your category tree.</p>',11)),s(a,{src:"/images/magic-ai/marketplace-features-scope.png",alt:"Scope section with Select Attributes switched on, revealing the required Allowed Attributes list, plus Suggest Categories"}),e[7]||(e[7]=o('<h4 id="select-attributes" tabindex="-1">Select Attributes <a class="header-anchor" href="#select-attributes" aria-label="Permalink to &quot;Select Attributes&quot;">​</a></h4><p>Whether you want to restrict which attributes the AI may fill.</p><ul><li><strong>When off</strong> — every attribute the seller can edit on that product is eligible.</li><li><strong>When on</strong> — only the attributes you pick in <strong>Allowed Attributes</strong> are eligible, and that field becomes <strong>required</strong>.</li></ul><h4 id="allowed-attributes" tabindex="-1">Allowed Attributes <a class="header-anchor" href="#allowed-attributes" aria-label="Permalink to &quot;Allowed Attributes&quot;">​</a></h4><p>The list of attributes the AI may propose values for. Only appears — and is only required — while <strong>Select Attributes</strong> is on.</p><p><strong>Why you might narrow it:</strong> the AI is good at prose and descriptive attributes and less reliable on values with commercial consequences. Restricting it to description, meta fields, colour and material keeps it away from anything a mistake would be expensive on.</p><p><strong>Some fields are never generated, whatever you choose here.</strong> Image, file, barcode and yes/no fields are excluded by their nature, and <strong>SKU</strong>, <strong>URL Key</strong>, <strong>Product Number</strong>, <strong>Barcode Value</strong>, <strong>Tax Category</strong> and <strong>RMA Rule</strong> are always excluded because they are identifiers or commercial settings rather than descriptive content.</p><h4 id="suggest-categories" tabindex="-1">Suggest Categories <a class="header-anchor" href="#suggest-categories" aria-label="Permalink to &quot;Suggest Categories&quot;">​</a></h4><p>Whether the AI also proposes categories for the product.</p><ul><li><strong>When on</strong> — the AI picks from <strong>all</strong> categories on your marketplace and the proposals appear under <strong>Categories</strong> in the review step, where the seller can accept or ignore them. A proposed category the AI invented that does not match your tree is skipped with a note.</li><li><strong>When off</strong> — categories are skipped entirely and the seller assigns them by hand.</li></ul><p><strong>Affects:</strong> sellers directly, and the storefront indirectly — categories decide where a product is found, so this setting quietly influences catalog navigation.</p><h2 id="how-the-settings-depend-on-each-other" tabindex="-1">How the settings depend on each other <a class="header-anchor" href="#how-the-settings-depend-on-each-other" aria-label="Permalink to &quot;How the settings depend on each other&quot;">​</a></h2><p>Magic AI is a chain: a seller can only generate when every link holds. In order:</p><ol><li><strong>Configure → Magic AI → General → Enabled</strong> must be on.</li><li><strong>Configure → Magic AI → Marketplace Features → Product Content Generation → Enable</strong> must be on.</li><li>A <strong>provider API key</strong> must be set for the provider that owns the chosen model.</li><li>The individual seller&#39;s <strong>Magic AI Enabled</strong> must not be switched off.</li><li>The seller must have generations <strong>remaining</strong> in the current period.</li><li>The seller&#39;s role must grant <strong>Generate Content With Magic AI</strong>.</li></ol><p>Break any one and the seller is refused, with a message naming the reason:</p><table tabindex="0"><thead><tr><th>What is missing</th><th>What the seller is told</th></tr></thead><tbody><tr><td>Either master switch is off</td><td><em>Content generation is currently turned off for this store.</em></td></tr><tr><td>The seller&#39;s own switch is off</td><td><em>Content generation is not enabled for your shop. Please contact the store administrator.</em></td></tr><tr><td>The quota is spent</td><td><em>You have used all your content generations for this period.</em></td></tr><tr><td>The provider did not respond</td><td><em>Couldn&#39;t generate content just now</em> — and no generation is consumed</td></tr></tbody></table><h3 id="settings-that-reveal-or-require-other-settings" tabindex="-1">Settings that reveal or require other settings <a class="header-anchor" href="#settings-that-reveal-or-require-other-settings" aria-label="Permalink to &quot;Settings that reveal or require other settings&quot;">​</a></h3><ul><li><strong>Allow Reference Images</strong> reveals <strong>Vision Model</strong> and <strong>Maximum Reference Images</strong>. Switch it off and both disappear, because neither has any meaning without it.</li><li><strong>Select Attributes</strong> reveals <strong>Allowed Attributes</strong>, and makes it <strong>required</strong> — turning the restriction on without naming any attribute is not a valid configuration.</li><li><strong>Per Seller Limit</strong> and <strong>Limit Period</strong> are only meaningful together; a blank limit makes the period irrelevant.</li></ul><h3 id="settings-that-fall-back-rather-than-fail" tabindex="-1">Settings that fall back rather than fail <a class="header-anchor" href="#settings-that-fall-back-rather-than-fail" aria-label="Permalink to &quot;Settings that fall back rather than fail&quot;">​</a></h3><ul><li><strong>Vision Model</strong> falls back to <strong>Model</strong> when blank.</li><li><strong>Model</strong> falls back to the platform&#39;s default text model when blank.</li><li><strong>Magic AI Generation Limit</strong> on a seller falls back to <strong>Per Seller Limit</strong> when blank.</li><li><strong>Magic AI Enabled</strong> on a seller is treated as <em>allowed</em> unless the admin has explicitly switched it off.</li></ul><h2 id="per-seller-controls" tabindex="-1">Per-seller controls <a class="header-anchor" href="#per-seller-controls" aria-label="Permalink to &quot;Per-seller controls&quot;">​</a></h2><p>Everything so far applies to the whole marketplace. Two seller attributes let you depart from it for one seller — to withhold the feature from someone producing poor listings, or to give a high-volume partner a bigger allowance.</p><p>Find them on <strong>Marketplace → Sellers</strong>, editing a seller, in the <strong>Settings</strong> group on the right-hand side of the form, below the commission and product-type controls.</p>',23)),s(a,{src:"/images/magic-ai/seller-magic-ai-controls.png",alt:"Magic AI Enabled and Magic AI Generation Limit on the admin seller edit form"}),e[8]||(e[8]=o('<p><strong>Magic AI Enabled:</strong> whether this seller may use Magic AI. Sellers are allowed by default, so this is a switch you use to take access <em>away</em> — from a seller producing poor listings, or one you have not yet decided to trust with it. It cannot grant access while either master switch is off.</p><p><strong>Magic AI Generation Limit:</strong> this seller&#39;s own allowance, counted over the marketplace-wide <strong>Limit Period</strong>. <strong>Leave it blank and the seller follows Per Seller Limit.</strong> Enter a number and it wins for that seller — higher for a high-volume partner, lower for a seller who has been wasteful.</p><p><strong>Practical example:</strong> with <strong>Per Seller Limit</strong> at 50 monthly, a large partner given a limit of 500 gets 500 per month, a seller given 0 gets none, and everyone left blank gets 50.</p><h3 id="what-the-seller-sees" tabindex="-1">What the seller sees <a class="header-anchor" href="#what-the-seller-sees" aria-label="Permalink to &quot;What the seller sees&quot;">​</a></h3><p>A seller does not have to guess where they stand. <strong>Manage Profile</strong> carries a read-only <strong>Shop Information</strong> panel that reports their Magic AI position back to them.</p><p>This is the screen to point a seller at when they ask why generation has stopped working — it shows their allowance and how much of it is gone, without them needing to contact you.</p>',6)),s(a,{src:"/images/magic-ai/seller-shop-information.png",alt:"Shop Information panel showing Magic AI enabled, generation limit, usage in the current period and the limit period"}),e[9]||(e[9]=o('<p>It states whether Magic AI is enabled for their shop and, when it is, their <strong>Generation Limit</strong>, how much they have <strong>Used In Current Period</strong>, and the <strong>Limit Period</strong> those figures are counted over. An unlimited seller sees <strong>Unlimited</strong>. See <a href="/sellers/seller-profile">Manage Profile</a>.</p><div class="info custom-block"><p class="custom-block-title">Roles can withhold it separately</p><p>Even on a seller account with Magic AI enabled, a team member only gets the button if their role grants <strong>Generate Content With Magic AI</strong>. A seller can therefore let their own staff write listings by hand while keeping generation to themselves. See <a href="/sellers/seller-user-role-management">Seller Users &amp; Roles</a>.</p></div><h2 id="using-magic-ai-as-a-seller" tabindex="-1">Using Magic AI as a seller <a class="header-anchor" href="#using-magic-ai-as-a-seller" aria-label="Permalink to &quot;Using Magic AI as a seller&quot;">​</a></h2><p>With everything configured, the seller opens a product and selects <strong>Generate content</strong> in the form header. A two-step dialog opens: <strong>Describe</strong>, then <strong>Review</strong>.</p><p><strong>Step 1: Describe.</strong> The seller writes a short description of the product — this is the prompt. It must be between <strong>10 and 2,000 characters</strong>, and a counter tracks it. Where the admin allows it they attach <strong>reference images</strong>, and tick <strong>which fields to fill</strong> from a row of chips; eligible fields come pre-selected, and the dialog notes that <em>fields you have already filled are excluded</em> when overwriting is off. A meter along the bottom shows generations used against the limit before a single one is spent.</p>',5)),s(a,{src:"/images/magic-ai/dialog-describe.png",alt:"Describe step with a written prompt, the character counter, reference image slots, the fields-to-fill chips and the generations-used meter"}),e[10]||(e[10]=o("<p><strong>Step 2: Generating.</strong> The AI writes the content — usually five to fifteen seconds.</p><p><strong>Step 3: Review.</strong> Each proposal is a card marked <strong>new</strong> or <strong>replaces</strong>, with any previous value struck through, and suggested <strong>Categories</strong> appear alongside. Anything the AI could not use is skipped with the reason — no matching option, a value that did not fit the field, or one that failed the field&#39;s own validation rule. A running meter shows generations used against the limit, and <strong>Regenerate this field</strong> re-runs a single field at the cost of one generation.</p>",2)),s(a,{src:"/images/magic-ai/generated.png",alt:"Magic AI review step — proposed fields marked new or replaces, with previous values struck through"}),e[11]||(e[11]=t("p",null,[t("strong",null,"Step 4: Apply."),r(" Applying "),t("strong",null,"only fills the form"),r(". If the seller opted in, their uploaded reference photos are reused as the product's images. Nothing is stored until the product is saved, and the listing then follows the normal "),t("a",{href:"/catalog/product-management#drafts-submission-and-approval"},"approval flow"),r(".")],-1)),s(a,{src:"/images/magic-ai/applied.png",alt:"Magic AI confirmation — fields updated on the product form, pending save"}),e[12]||(e[12]=t("p",null,[t("strong",null,"Step 5: Save the product."),r(" The dialog closes and the seller is back on the product form with the generated values sitting in the fields — still unsaved. Nothing has reached the catalog yet, and navigating away now would discard the lot.")],-1)),e[13]||(e[13]=t("p",null,[r("Which save actions appear depends on the state of the listing. A "),t("strong",null,"draft"),r(" offers two: "),t("strong",null,"Save as Draft"),r(" keeps it private and unfinished, while "),t("strong",null,"Submit"),r(" sends it into the approval flow. A listing that is already live simply offers "),t("strong",null,"Save Product"),r(".")],-1)),s(a,{src:"/images/magic-ai/save-draft-or-submit.png",alt:"Draft product header offering Generate content, Save as Draft and Submit"}),e[14]||(e[14]=o('<p><strong>Step 6: Approval.</strong> Once saved, the listing takes its place in <strong>Catalog → Products</strong> with its current state shown against it — <strong>Draft</strong> while the seller is still working on it, <strong>Waiting For Approval</strong> once submitted, and <strong>Approved</strong> when the admin has passed it.</p><p>Generated content is treated no differently from hand-written content here. It is reviewed by the admin like any other listing, and only reaches the storefront on approval — see <a href="/catalog/product-management#drafts-submission-and-approval">Product Management</a>.</p>',2)),s(a,{src:"/images/magic-ai/products-after-save.png",alt:"Seller products list showing listings marked Approved, Draft and Waiting For Approval"}),e[15]||(e[15]=t("div",{class:"warning custom-block"},[t("p",{class:"custom-block-title"},"The generation is spent before you save"),t("p",null,"Quota is counted when the AI answers, not when the seller applies or saves. A seller who generates, dislikes the result and closes the dialog has still used one of their generations. This is deliberate — the provider has already been paid for that call — but it surprises sellers, so it is worth saying out loud when you introduce the feature.")],-1)),e[16]||(e[16]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"Write a specific, factual prompt"),t("p",null,[r("Materials, size, intended use, audience. The dialog's own hint says it best — "),t("em",null,"the more specific you are, the better the result"),r(" — and a good prompt is the cheapest way to reduce the editing a seller does afterwards.")])],-1))])}const y=n(g,[["render",d]]);export{b as __pageData,y as default};
